<?php if(!$rows):?><p class="butchery-empty">Aucune sortie dans cette sélection.</p><?php else:?>
<table class="enterprise-table" <?=$filters?'id="distributionsTable" data-butchery-history="distributions"':''?>><thead><tr><th>Bon / date</th><th>Site / destination</th><th>Produit / format</th><th>Sacs</th><th>Poids</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr data-status="<?=e($row['status'])?>" data-date="<?=e(substr($row['distributed_at'],0,10))?>"><td><strong><?=e($row['official_document_number']?:$row['exit_voucher'])?></strong><small><?=e($date($row['distributed_at']))?></small></td><td><strong><?=e($row['recipient_name'])?></strong><small><?=e($row['site_code'])?></small></td><td><?=e($row['product_name'])?><small><?=e($row['format_name'])?></small></td><td data-order="<?=e($row['quantity_bags'])?>"><?=e($number($row['quantity_bags']))?></td><td data-order="<?=e($row['total_weight_kg'])?>"><?=e($number($row['total_weight_kg'],3))?> kg</td><td><span class="butchery-status <?=$row['status']==='validated'?'butchery-status-success':'butchery-status-muted'?>"><?=e($labels[$row['status']]??$row['status'])?></span></td><td><button type="button" class="btn-secondary" data-workspace-modal-open="distribution-detail-<?=e($row['id'])?>" aria-label="<?=e('Consulter '.$row['exit_voucher'])?>">Détails</button></td></tr><?php endforeach;?></tbody></table><?php endif;?>
